        compressibilityZ: 0.98,
      },
      hourlyConsumption: [{ hour: 0, value: 12.3 }],
    };

    const parsed = parseIngestPayload(raw);

    expect(parsed.deviceSerialNo).toBe("EVC-TEST-001");
