  onCloseMobile: () => void;
  onToggleDesktop: () => void;
}

// Responsive dashboard navigation with desktop collapse and mobile drawer modes.
export function Sidebar({ collapsed, mobileOpen, onCloseMobile, onToggleDesktop }: SidebarProps) {
  return (
