            <p className="truncate text-xs text-slate-500 dark:text-slate-400">Fleet Telemetry v1</p>
          </div>
        )}
        {showDesktopToggle && (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            className="ml-auto hidden text-slate-500 dark:text-slate-400 lg:inline-flex"
            onClick={onToggleDesktop}
