          >
            {collapsed ? <ChevronRight className="h-4 w-4" /> : <ChevronLeft className="h-4 w-4" />}
          </Button>
        )}
        {!showDesktopToggle && (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            className="ml-auto text-slate-500 dark:text-slate-400"
            onClick={onCloseMobile}
            aria-label="Close sidebar"
          >
            <X className="h-4 w-4" />
          </Button>
        )}
